from sortedcontainers import SortedDict

class SummaryRanges:
    def __init__(self):
        self.intervals = SortedDict()

    def addNum(self, value: int) -> None:
        s = e = value
        keys = self.intervals.keys()
        idx = self.intervals.bisect_right(value)
        if idx > 0:
            prev_s = keys[idx - 1]
            prev_e = self.intervals[prev_s]
            if prev_e >= value:
                return
            if prev_e + 1 == value:
                s = prev_s
                del self.intervals[prev_s]
        if idx < len(keys):
            next_s = keys[idx]
            next_e = self.intervals[next_s]
            if next_s == value:
                return
            if next_s - 1 == value:
                e = next_e
                del self.intervals[next_s]
        self.intervals[s] = e

    def getIntervals(self) -> list[list[int]]:
        return [[s, e] for s, e in self.intervals.items()]

